SELECT p.id, COUNT(e.id) AS n, MIN(e.price) AS min_px, MAX(e.price) AS max_px, MIN(e.observed_at) AS first_obs_display, MAX(e.observed_at) AS last_obs_display, SUM(e.delivery_status NOT IN ('APPLIED','LEGACY')) AS non_accepted, SUM(e.price > p.entry_price) AS n_above_entry, SUM(e.price <= p.stop_loss) AS n_le_sl, SUM(e.price >= p.take_profit) AS n_ge_tp FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id ORDER BY p.id;